package dev.zomboid.autopsy;import java.util.*;public class RenderChecks {public static class J implements Iterable<Object>{public Object value;public Map<String,J> map=new HashMap<>();public List<Object> list=new ArrayList<>();public J(Object v){value=v;}public J put(String k,J v){map.put(k,v);return this;}public boolean has(String k){return map.containsKey(k);}public J get(String k){return map.get(k);}public J getAsJsonObject(){return this;}public double getAsDouble(){return ((Number)value).doubleValue();}public String getAsString(){return value.toString();}public boolean getAsBoolean(){return (Boolean)value;}public Iterator<Object> iterator(){return list.iterator();}}public static class Font {public int width(String s){return s.length()*6;}public List<String> split(Object s,int width){String text=s.toString();List<String> out=new ArrayList<>();int count=Math.max(1,width/6);for(int i=0;i<text.length();i+=count)out.add(text.substring(i,Math.min(text.length(),i+count)));return out;}}public static class Gui {public int sprites;public boolean scissor;public List<String> text=new ArrayList<>();public void fill(int x,int y,int a,int b,int color){}public void drawString(Object font,Object s,int x,int y,int color,boolean shadow){text.add(s.toString());}public void blit(Object tex,int x,int y,int width,int height,float u,float v,int sw,int sh,int tw,int th){sprites++;}public void enableScissor(int x,int y,int a,int b){scissor=true;}public void disableScissor(){scissor=false;}}static J part(String name,double hp,String injury){J wounds=new J(null);wounds.list.add(new J(injury));return new J(null).put("part",new J(name)).put("hp",new J(hp)).put("max",new J(10)).put("wounds",wounds);}public static void main(String[] args){J body=new J(null);body.list.add(part("HEAD",1,"bleed"));body.list.add(part("LEFT_ARM",9,"cut"));J detail=new J(null).put("body24",body).put("damage24",new J("generic"));Gui gui=new Gui();if(!Autopsy.render(gui,new Font(),500,320,3000,new dev.survivorcreator.hearing.DeathReport(),detail))throw new AssertionError("report render failed");if(gui.sprites!=2||gui.scissor||com.mojang.blaze3d.systems.RenderSystem.red!=1)throw new AssertionError("render state leaked");if(gui.text.stream().noneMatch(s->s.contains("Brazo")))throw new AssertionError("wound annotations missing");if(gui.text.stream().noneMatch(s->s.contains("Cabeza")))throw new AssertionError("severe wound missing");System.out.println("Passed full autopsy rendering, severity filtering and graphics state checks (API doubles)");}}

